3	import (
4		"errors"
5		"fmt"
6		"strings"
7	)
8	
9	var (
10		errHarnessModelIncompatible = errors.New("agent: harness model incompatible")
11		errProfilePinConflict       = errors.New("agent: profile pin conflict")
12		errNoProfileCandidate       = errors.New("agent: no profile candidate")
13		errUnknownProfile           = errors.New("agent: unknown profile")
14		errNoLiveProvider           = errors.New("agent: no live provider")
15		errUnknownProvider          = errors.New("agent: unknown provider")
16	)
17	
18	// ErrUnknownProvider reports an explicit Provider pin that is not present in
19	// the service configuration. This is a pre-dispatch pin failure: the caller
20	// asked for a provider name that the service has no record of, so no route
21	// can be constructed.
22	type ErrUnknownProvider struct {
23		// Provider is the provider name supplied by the caller.
24		Provider string
25		// KnownProviders is the set of provider names the service knows about
26		// (empty when no ServiceConfig is configured).
27		KnownProviders []string
28	}
29	
30	func (e ErrUnknownProvider) Error() string {
31		if len(e.KnownProviders) == 0 {
32			return fmt.Sprintf("unknown provider %q", e.Provider)
33		}
34		return fmt.Sprintf("unknown provider %q; known providers: %s", e.Provider, strings.Join(e.KnownProviders, ", "))
35	}
36	
37	func (e ErrUnknownProvider) Is(target error) bool {
38		switch target.(type) {
39		case ErrUnknownProvider, *ErrUnknownProvider:
40			return true
41		default:
42			return errors.Is(errUnknownProvider, target)
43		}
44	}
45	
46	func (e ErrUnknownProvider) Unwrap() error {
47		return errUnknownProvider
48	}
