50	// DecisionWithCandidates is implemented by routing errors that retain the
51	// evaluated candidate trace for a failed ResolveRoute call.
52	type DecisionWithCandidates interface {
53		error
54		// RouteCandidates returns the evaluated candidates that led to the error.
55		RouteCandidates() []RouteCandidate
56	}
57	
58	type routeDecisionError struct {
59		err        error
60		candidates []RouteCandidate
61	}
62	
63	func (e *routeDecisionError) Error() string {
64		return e.err.Error()
65	}
66	
67	func (e *routeDecisionError) Unwrap() error {
68		return e.err
69	}
70	
71	func (e *routeDecisionError) RouteCandidates() []RouteCandidate {
72		return append([]RouteCandidate(nil), e.candidates...)
73	}
