75	// ErrHarnessModelIncompatible reports an explicit Harness+Model pin that the
76	// harness allow-list cannot serve.
77	//
78	// DDx preflight callers should use errors.As to extract Harness, Model, and
79	// SupportedModels for worker logs or bead failure records. errors.Is matches a
80	// zero-value ErrHarnessModelIncompatible, even after callers wrap the error with
81	// fmt.Errorf and %w.
82	type ErrHarnessModelIncompatible struct {
83		// Harness is the canonical harness name supplied by the caller.
84		Harness string
85		// Model is the exact concrete model pin supplied by the caller.
86		Model string
87		// SupportedModels is the harness allow-list that rejected Model.
88		SupportedModels []string
89	}
90	
91	func (e ErrHarnessModelIncompatible) Error() string {
92		return fmt.Sprintf("model %q is not supported by harness %q; supported models: %s", e.Model, e.Harness, strings.Join(e.SupportedModels, ", "))
93	}
94	
95	func (e ErrHarnessModelIncompatible) Is(target error) bool {
96		switch target.(type) {
97		case ErrHarnessModelIncompatible, *ErrHarnessModelIncompatible:
98			return true
99		default:
100			return errors.Is(errHarnessModelIncompatible, target)
101		}
102	}
103	
104	func (e ErrHarnessModelIncompatible) Unwrap() error {
105		return errHarnessModelIncompatible
106	}
107	
108	// ErrProfilePinConflict reports an explicit Profile whose placement constraint
109	// contradicts another explicit caller pin.
110	//
111	// DDx preflight callers should use errors.As to extract Profile,
112	// ConflictingPin, and ProfileConstraint for worker logs or bead failure
113	// records. errors.Is matches a zero-value ErrProfilePinConflict, even after
114	// callers wrap the error with fmt.Errorf and %w.
115	type ErrProfilePinConflict struct {
116		// Profile is the explicit profile requested by the caller.
117		Profile string
118		// ConflictingPin names the explicit pin that violates the profile, such as
119		// "Harness=claude" or "Model=local-model".
120		ConflictingPin string
121		// ProfileConstraint is a short description of the profile placement rule,
122		// such as "local-only" or "subscription-only".
123		ProfileConstraint string
124	}
125	
126	func (e ErrProfilePinConflict) Error() string {
127		return fmt.Sprintf("profile %q requires %s but conflicts with %s", e.Profile, e.ProfileConstraint, e.ConflictingPin)
128	}
129	
130	func (e ErrProfilePinConflict) Is(target error) bool {
131		switch target.(type) {
132		case ErrProfilePinConflict, *ErrProfilePinConflict:
133			return true
134		default:
135			return errors.Is(errProfilePinConflict, target)
136		}
137	}
138	
139	func (e ErrProfilePinConflict) Unwrap() error {
140		return errProfilePinConflict
141	}
