191	// ErrNoLiveProvider reports that profile-tier escalation walked the entire
192	// cheap → standard → smart ladder without finding a live provider that
193	// could serve the request. The message names the prompt size and tool
194	// requirement so operators know what capability is missing across all
195	// tiers, rather than the engine's "no viable routing candidate" jargon.
196	type ErrNoLiveProvider struct {
197		PromptTokens  int
198		RequiresTools bool
199		StartingTier  string
200	}
201	
202	func (e ErrNoLiveProvider) Error() string {
203		return fmt.Sprintf("no live provider supports prompt of %d tokens with tools=%v at tier ≥ %s",
204			e.PromptTokens, e.RequiresTools, e.StartingTier)
205	}
206	
207	func (e ErrNoLiveProvider) Is(target error) bool {
208		switch target.(type) {
209		case ErrNoLiveProvider, *ErrNoLiveProvider:
210			return true
211		default:
212			return errors.Is(errNoLiveProvider, target)
213		}
214	}
215	
