1	package fizeau
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"strings"
8		"time"
9	
10		"github.com/DocumentDrivenDX/fizeau/internal/harnesses"
11		claudeharness "github.com/DocumentDrivenDX/fizeau/internal/harnesses/claude"
12		codexharness "github.com/DocumentDrivenDX/fizeau/internal/harnesses/codex"
13		geminiharness "github.com/DocumentDrivenDX/fizeau/internal/harnesses/gemini"
14		"github.com/DocumentDrivenDX/fizeau/internal/modelcatalog"
15		"github.com/DocumentDrivenDX/fizeau/internal/routing"
16	)
17	
18	var loadRoutingCatalog = modelcatalog.Default
19	
20	// ResolveRoute resolves an under-specified RouteRequest to a concrete
21	// (Harness, Provider, Model) decision per CONTRACT-003.
22	//
23	// The implementation delegates to internal/routing.Resolve — the single
24	// routing engine that consolidates DDx-side harness-tier ranking and
25	// agent-side provider failover ordering.
26	func (s *service) ResolveRoute(ctx context.Context, req RouteRequest) (*RouteDecision, error) {
27		if err := ValidatePowerBounds(req.MinPower, req.MaxPower); err != nil {
28			return nil, err
29		}
30		if err := ValidateRole(req.Role); err != nil {
31			return nil, err
32		}
33		if err := ValidateCorrelationID(req.CorrelationID); err != nil {
34			return nil, err
35		}
36		s.ensurePrimaryQuotaRefresh(ctx, quotaRefreshAsync)
37		cat := serviceRoutingCatalog()
38		profile := req.Profile
39		if profile == "" {
40			profile = reqProfileFromModelRef(cat, req.ModelRef)
41		}
42		modelRef := reqModelRefStripProfile(cat, req.ModelRef)
43		providerPreference, err := providerPreferenceForProfile(cat, profile)
44		if err != nil {
45			return &RouteDecision{}, err
46		}
47		in := s.buildRoutingInputsWithCatalog(ctx, cat)
48	
49		rReq := routing.Request{
50			Profile:               profile,
51			ModelRef:              modelRef,
52			Model:                 req.Model,
53			Provider:              req.Provider,
54			Harness:               req.Harness,
55			Reasoning:             effectiveReasoningString(req.Reasoning),
56			Permissions:           req.Permissions,
57			ProviderPreference:    providerPreference,
58			EstimatedPromptTokens: req.EstimatedPromptTokens,
59			RequiresTools:         req.RequiresTools,
60			MinPower:              req.MinPower,
61			MaxPower:              req.MaxPower,
62		}
63		s.applyRouteAttemptCooldowns(&in)
64		dec, err := routing.Resolve(rReq, in)
65		if err != nil {
66			if escalated, edec, eerr := escalateProfileLadder(rReq, in, err); escalated {
67				dec = edec
68				err = eerr
69			}
70		}
71		result := routeDecisionFromInternal(dec)
72		if err != nil {
73			if result == nil {
74				result = &RouteDecision{}
75			}
76			return result, publicRoutingError(err, result.Candidates)
77		}
78		// Cache the decision so RouteStatus can surface LastDecision.
79		if result != nil {
80			result.Model = resolveSubprocessModelAlias(result.Harness, result.Model)
81			result.Power = catalogPowerForModel(cat, result.Model)
82		}
83		s.cacheRouteDecision(req.Model, result)
84		return result, nil
85	}
86	
87	func routeDecisionFromInternal(dec *routing.Decision) *RouteDecision {
88		if dec == nil {
89			return nil
90		}
91		return &RouteDecision{
92			Harness:    dec.Harness,
93			Provider:   dec.Provider,
94			Endpoint:   dec.Endpoint,
95			Model:      dec.Model,
96			Reason:     dec.Reason,
97			Candidates: routeCandidatesFromInternal(dec.Candidates),
98		}
99	}
100	
101	func routeCandidatesFromInternal(candidates []routing.Candidate) []RouteCandidate {
102		if len(candidates) == 0 {
103			return nil
104		}
105		out := make([]RouteCandidate, len(candidates))
106		for i, candidate := range candidates {
107			out[i] = routeCandidateFromInternal(candidate)
108		}
109		return out
110	}
111	
112	func routeCandidateFromInternal(candidate routing.Candidate) RouteCandidate {
113		return RouteCandidate{
114			Harness:            candidate.Harness,
115			Provider:           candidate.Provider,
116			Endpoint:           candidate.Endpoint,
117			Model:              candidate.Model,
118			Score:              candidate.Score,
119			CostUSDPer1kTokens: candidate.CostUSDPer1kTokens,
120			CostSource:         candidate.CostSource,
121			Eligible:           candidate.Eligible,
122			Reason:             candidate.Reason,
123			FilterReason:       publicFilterReason(candidate),
124			Components: RouteCandidateComponents{
125				Power:            candidate.Power,
126				Cost:             candidate.CostUSDPer1kTokens,
127				CostClass:        candidate.CostClass,
128				LatencyMS:        candidate.LatencyMS,
129				SpeedTPS:         candidate.SpeedTPS,
130				SuccessRate:      candidate.SuccessRate,
131				QuotaOK:          candidate.QuotaOK,
132				QuotaPercentUsed: candidate.QuotaPercentUsed,
133				QuotaTrend:       candidate.QuotaTrend,
134				Capability:       capabilityScoreForCostClass(candidate.CostClass),
135			},
136		}
137	}
138	
139	// publicFilterReason maps the typed FilterReason emitted by the internal
140	// routing engine to the public FilterReason* string constant. The internal
141	// constants are defined to share string values with the public surface, so
142	// this is a one-line passthrough — there is no string parsing.
143	func publicFilterReason(c routing.Candidate) string {
144		if c.Eligible {
145			return ""
146		}
147		return string(c.FilterReason)
148	}
149	
150	// capabilityScoreForCostClass maps the harness cost class to a coarse
151	// numeric capability proxy. Mirrors the engine's costClassRank ordering
152	// (more expensive ≈ more capable) for reporting purposes only.
153	func capabilityScoreForCostClass(class string) float64 {
154		switch class {
155		case "local":
156			return 0
157		case "cheap":
158			return 1
159		case "medium", "":
160			return 2
161		case "expensive":
162			return 3
163		case "experimental":
164			return -1
165		default:
166			return 0
167		}
168	}
169	
170	// escalateProfileLadder walks routing.ProfileEscalationLadder when Resolve
171	// returns a "no eligible candidate" error and the request's profile is in
172	// the ladder. Returns (true, decision, nil) when a higher tier resolves to
173	// an eligible candidate, or (true, nil, *routing.ErrNoLiveProvider) when
174	// the entire remaining ladder is also empty. Returns (false, _, _) when
175	// escalation does not apply (hard pin error, profile not in ladder, etc.).
176	func escalateProfileLadder(req routing.Request, in routing.Inputs, origErr error) (bool, *routing.Decision, error) {
177		if origErr == nil || req.Profile == "" {
178			return false, nil, nil
179		}
180		if !shouldEscalateOnError(origErr) {
181			return false, nil, nil
182		}
183		startIdx := -1
184		for i, p := range routing.ProfileEscalationLadder {
185			if p == req.Profile {
186				startIdx = i
187				break
188			}
189		}
190		if startIdx < 0 {
191			return false, nil, nil
192		}
193		for i := startIdx + 1; i < len(routing.ProfileEscalationLadder); i++ {
194			probe := req
195			probe.Profile = routing.ProfileEscalationLadder[i]
196			dec, err := routing.Resolve(probe, in)
197			if err == nil && dec != nil && dec.Harness != "" {
198				return true, dec, nil
199			}
200		}
201		return true, nil, &routing.ErrNoLiveProvider{
202			PromptTokens:  req.EstimatedPromptTokens,
203			RequiresTools: req.RequiresTools,
204			StartingTier:  req.Profile,
205		}
206	}
207	
208	// shouldEscalateOnError gates ladder escalation to "no eligible candidate"
209	// errors. Hard caller-pin conflicts (ErrHarnessModelIncompatible,
210	// ErrProfilePinConflict) are surfaced as-is — escalating past an explicit
211	// pin would silently change the caller's intent.
212	func shouldEscalateOnError(err error) bool {
213		var modelErr *routing.ErrHarnessModelIncompatible
214		if errors.As(err, &modelErr) {
215			return false
216		}
217		var pinErr *routing.ErrProfilePinConflict
218		if errors.As(err, &pinErr) {
219			return false
220		}
221		return true
222	}
223	
224	func publicRoutingError(err error, candidates []RouteCandidate) error {
225		var modelErr *routing.ErrHarnessModelIncompatible
226		if errors.As(err, &modelErr) {
227			return withRouteCandidates(&ErrHarnessModelIncompatible{
228				Harness:         modelErr.Harness,
229				Model:           modelErr.Model,
230				SupportedModels: append([]string(nil), modelErr.SupportedModels...),
231			}, candidates)
232		}
233		var profileErr *routing.ErrProfilePinConflict
234		if errors.As(err, &profileErr) {
235			return withRouteCandidates(&ErrProfilePinConflict{
236				Profile:           profileErr.Profile,
237				ConflictingPin:    profileErr.ConflictingPin,
238				ProfileConstraint: profileErr.ProfileConstraint,
239			}, candidates)
240		}
241		var noProfileErr *routing.ErrNoProfileCandidate
242		if errors.As(err, &noProfileErr) {
243			return withRouteCandidates(&ErrNoProfileCandidate{
244				Profile:           noProfileErr.Profile,
245				MissingCapability: noProfileErr.MissingCapability,
246				Rejected:          noProfileErr.Rejected,
247			}, candidates)
248		}
249		var noLiveErr *routing.ErrNoLiveProvider
250		if errors.As(err, &noLiveErr) {
251			return withRouteCandidates(&ErrNoLiveProvider{
252				PromptTokens:  noLiveErr.PromptTokens,
253				RequiresTools: noLiveErr.RequiresTools,
254				StartingTier:  noLiveErr.StartingTier,
255			}, candidates)
256		}
257		return withRouteCandidates(err, candidates)
258	}
259	
260	func withRouteCandidates(err error, candidates []RouteCandidate) error {
261		if err == nil || len(candidates) == 0 {
262			return err
263		}
264		return &routeDecisionError{
265			err:        err,
266			candidates: append([]RouteCandidate(nil), candidates...),
267		}
268	}
269	
270	func (s *service) applyRouteAttemptCooldowns(in *routing.Inputs) {
271		if in == nil {
272			return
273		}
274		ttl := s.routeAttemptTTL()
275		records := s.activeRouteAttempts(time.Now(), ttl)
276		if len(records) == 0 {
277			return
278		}
279		if in.ProviderCooldowns == nil {
280			in.ProviderCooldowns = make(map[string]time.Time)
281		}
282		if in.CooldownDuration <= 0 {
283			in.CooldownDuration = ttl
284		}
285		for _, record := range records {
286			if record.key.Provider != "" {
287				existing, ok := in.ProviderCooldowns[record.key.Provider]
288				if !ok || record.recordedAt.After(existing) {
289					in.ProviderCooldowns[record.key.Provider] = record.recordedAt
290				}
291			}
292			if record.key.Provider == "" && record.key.Harness != "" {
293				for i := range in.Harnesses {
294					if in.Harnesses[i].Name == record.key.Harness {
295						in.Harnesses[i].InCooldown = true
296					}
297				}
298			}
299		}
300	}
301	
302	func (s *service) routeAttemptTTL() time.Duration {
303		if s.opts.ServiceConfig == nil {
304			return defaultRouteAttemptCooldown
305		}
306		ttl := s.opts.ServiceConfig.HealthCooldown()
307		if ttl <= 0 {
308			return defaultRouteAttemptCooldown
309		}
310		return ttl
311	}
312	
313	// reqProfileFromModelRef returns ref when ref is a known profile alias,
314	// or "" otherwise. The contract puts ModelRef and Profile in the same field.
315	func reqProfileFromModelRef(cat *modelcatalog.Catalog, ref string) string {
316		if cat == nil {
317			return ""
318		}
319		if _, ok := cat.Profile(ref); ok {
320			return ref
321		}
322		return ""
323	}
324	
325	// reqModelRefStripProfile returns "" when ref is a known profile alias,
326	// or ref otherwise.
327	func reqModelRefStripProfile(cat *modelcatalog.Catalog, ref string) string {
328		if cat == nil {
329			return ref
330		}
331		if _, ok := cat.Profile(ref); ok {
332			return ""
333		}
334		return ref
335	}
336	
337	// buildRoutingInputs assembles routing.Inputs from the service's registry
338	// and ServiceConfig. When the service has a catalog cache attached (v0.9.2+),
339	// each configured provider's ProviderEntry is populated with DiscoveredIDs
340	// from the cache's live /v1/models probe, so routing.FuzzyMatch matches the
341	// request against IDs the server actually serves rather than the configured
342	// default-model string.
343	//
344	// ctx is used for cache probes with a short deadline; the cache's
345	// stale-while-revalidate flow makes most calls non-blocking.
346	func (s *service) buildRoutingInputs(ctx context.Context) routing.Inputs {
347		return s.buildRoutingInputsWithCatalog(ctx, serviceRoutingCatalog())
348	}
349	
350	func (s *service) buildRoutingInputsWithCatalog(ctx context.Context, cat *modelcatalog.Catalog) routing.Inputs {
351		statuses := s.registry.Discover()
352		statusByName := make(map[string]harnesses.HarnessStatus, len(statuses))
353		for _, st := range statuses {
354			statusByName[st.Name] = st
355		}
356	
357		var entries []routing.HarnessEntry
358		for _, name := range s.registry.Names() {
359			cfg, ok := s.registry.Get(name)
360			if !ok {
361				continue
362			}
363			st := statusByName[name]
364			entry := routing.HarnessEntry{
365				Name:                name,
366				Surface:             cfg.Surface,
367				CostClass:           cfg.CostClass,
368				IsLocal:             cfg.IsLocal,
369				IsSubscription:      cfg.IsSubscription,
370				IsHTTPProvider:      cfg.IsHTTPProvider,
371				AutoRoutingEligible: cfg.AutoRoutingEligible,
372				TestOnly:            cfg.TestOnly,
373				ExactPinSupport:     cfg.ExactPinSupport,
374				DefaultModel:        cfg.DefaultModel,
375				SupportedModels:     subprocessHarnessModelIDs(name, cfg),
376				SupportedReasoning:  supportedReasoning(cfg),
377				MaxReasoningTokens:  cfg.MaxReasoningTokens,
378				SupportedPerms:      supportedPermissions(cfg),
379				SupportsTools:       true, // all builtin harnesses support tools today
380				Available:           st.Available,
381				QuotaOK:             true,
382				QuotaTrend:          routing.QuotaTrendUnknown,
383				// SubscriptionOK defaults to true and is refined by subscription
384				// harness quota caches below.
385				SubscriptionOK: true,
386			}
387			if name == "agent" && s.opts.ServiceConfig == nil {
388				entry.AutoRoutingEligible = false
389			}
390	
391			if name == "claude" {
392				dec := claudeharness.ReadClaudeQuotaRoutingDecision(time.Now(), 0)
393				entry.QuotaOK = dec.PreferClaude
394				entry.QuotaStale = !dec.Fresh && dec.SnapshotPresent
395				entry.SubscriptionOK = dec.PreferClaude
396				if dec.Snapshot != nil {
397					maxUsed := 0.0
398					if dec.Snapshot.FiveHourLimit > 0 {
399						maxUsed = float64(dec.Snapshot.FiveHourLimit-dec.Snapshot.FiveHourRemaining) / float64(dec.Snapshot.FiveHourLimit) * 100
400					}
401					if dec.Snapshot.WeeklyLimit > 0 {
402						weeklyUsed := float64(dec.Snapshot.WeeklyLimit-dec.Snapshot.WeeklyRemaining) / float64(dec.Snapshot.WeeklyLimit) * 100
403						if weeklyUsed > maxUsed {
404							maxUsed = weeklyUsed
405						}
406					}
407					entry.QuotaPercentUsed = int(maxUsed)
408					if maxUsed >= 90 {
409						entry.QuotaTrend = routing.QuotaTrendExhausting
410					} else if maxUsed >= 70 {
411						entry.QuotaTrend = routing.QuotaTrendBurning
412					} else if dec.Fresh {
413						entry.QuotaTrend = routing.QuotaTrendHealthy
414					}
415				}
416			}
417	
418			if name == "codex" {
419				dec := codexharness.ReadCodexQuotaRoutingDecision(time.Now(), 0)
420				entry.QuotaOK = dec.PreferCodex
421				entry.QuotaStale = !dec.Fresh && dec.SnapshotPresent
422				entry.SubscriptionOK = dec.PreferCodex
423				if dec.Snapshot != nil {
424					maxUsed := 0.0
425					for _, window := range dec.Snapshot.Windows {
426						if window.UsedPercent > maxUsed {
427							maxUsed = window.UsedPercent
428						}
429					}
430					entry.QuotaPercentUsed = int(maxUsed)
431					if maxUsed >= 90 {
432						entry.QuotaTrend = routing.QuotaTrendExhausting
433					} else if maxUsed >= 70 {
434						entry.QuotaTrend = routing.QuotaTrendBurning
435					} else if dec.Fresh {
436						entry.QuotaTrend = routing.QuotaTrendHealthy
437					}
438				}
439			}
440	
441			if name == "gemini" {
442				// Auth freshness is NOT quota. Only parsed quota evidence
443				// (from PTY /model manage capture) may mark Gemini as
444				// quota-OK for routing. Missing or stale quota evidence
445				// keeps Gemini out of automatic routing regardless of
446				// authentication state.
447				dec := geminiharness.ReadGeminiQuotaRoutingDecision(time.Now(), 0)
448				entry.QuotaOK = dec.PreferGemini
449				entry.QuotaStale = !dec.Fresh && dec.SnapshotPresent
450				entry.SubscriptionOK = dec.PreferGemini
451				if dec.Snapshot != nil {
452					maxUsed := dec.Snapshot.MaxUsedPercent()
453					entry.QuotaPercentUsed = int(maxUsed)
454					if len(dec.ExhaustedTiers) > 0 && len(dec.AvailableTiers) == 0 {
455						entry.QuotaTrend = routing.QuotaTrendExhausting
456					} else if maxUsed >= 90 {
457						entry.QuotaTrend = routing.QuotaTrendExhausting
458					} else if maxUsed >= 70 {
459						entry.QuotaTrend = routing.QuotaTrendBurning
460					} else if dec.Fresh {
461						entry.QuotaTrend = routing.QuotaTrendHealthy
462					}
463				}
464			}
465	
466			// Native "agent" harness: enumerate live configured provider endpoints.
467			if name == "agent" && s.opts.ServiceConfig != nil {
468				for _, pname := range s.opts.ServiceConfig.ProviderNames() {
469					pcfg, ok := s.opts.ServiceConfig.Provider(pname)
470					if !ok {
471						continue
472					}
473					entry.Providers = append(entry.Providers, s.liveProviderEntries(ctx, pname, pcfg, cat)...)
474				}
475				// Tool support for the agent harness is per-(provider, model);
476				// the harness-level baseline is whether ANY provider supports
477				// tools. Engine OR-combines harness and provider SupportsTools
478				// so this lets a per-model no_tools catalog flag actually fire
479				// the RequiresTools gate when every provider's resolved model
480				// is no-tools.
481				if len(entry.Providers) > 0 {
482					entry.SupportsTools = anyProviderSupportsTools(entry.Providers)
483				}
484			}
485			s.applySubscriptionRoutingCost(&entry, cat)
486			entries = append(entries, entry)
487		}
488		successRate, latencyMS := s.routeMetricSignals(time.Now(), s.routeAttemptTTL())
489		return routing.Inputs{
490			Harnesses:           entries,
491			ProviderSuccessRate: successRate,
492			ObservedLatencyMS:   latencyMS,
493			CatalogResolver:     serviceRoutingCatalogResolver(cat),
494			ModelEligibility:    serviceRoutingModelEligibility(cat),
495			ReasoningResolver:   serviceRoutingReasoningResolver(cat),
496		}
497	}
