591	func (s *service) liveProviderEntries(ctx context.Context, providerName string, pcfg ServiceProviderEntry, cat *modelcatalog.Catalog) []routing.ProviderEntry {
592		if providerUsesLiveDiscovery(pcfg.Type) && s.catalog != nil {
593			endpoints := modelDiscoveryEndpoints(pcfg)
594			out := make([]routing.ProviderEntry, 0, len(endpoints))
595			for _, endpoint := range endpoints {
596				ids, ok := s.probeEndpointDiscoveredIDs(ctx, pcfg, endpoint.BaseURL)
597				if !ok || len(ids) == 0 {
598					continue
599				}
600				routeName := providerName
601				if len(endpoints) > 1 {
602					routeName = endpointProviderRef(providerName, endpoint.Name)
603				}
604				entry := routing.ProviderEntry{
605					Name:               routeName,
606					BaseURL:            endpoint.BaseURL,
607					EndpointName:       endpoint.Name,
608					EndpointBaseURL:    endpoint.BaseURL,
609					DefaultModel:       pcfg.Model,
610					DiscoveredIDs:      ids,
611					DiscoveryAttempted: true,
612					ContextWindows:     buildProviderContextWindows(cat, pcfg.Model, ids),
613					SupportsTools:      providerSupportsTools(cat, pcfg.Model, ids),
614				}
615				s.applyEndpointRoutingCost(&entry, pcfg, cat)
616				out = append(out, entry)
617			}
618			return out
619		}
620		entry := routing.ProviderEntry{
621			Name:           providerName,
622			BaseURL:        pcfg.BaseURL,
623			DefaultModel:   pcfg.Model,
624			ContextWindows: buildProviderContextWindows(cat, pcfg.Model, nil),
625			SupportsTools:  providerSupportsTools(cat, pcfg.Model, nil),
626		}
627		s.applyEndpointRoutingCost(&entry, pcfg, cat)
628		return []routing.ProviderEntry{entry}
629	}
630	
631	// buildProviderContextWindows assembles the ContextWindows map for a
632	// ProviderEntry from the model catalog. Entries are added for the provider's
633	// configured DefaultModel and every DiscoveredID that has a non-zero
634	// context_window declared in the catalog. Models the catalog does not know
635	// about are omitted (engine treats missing entries as unknown context).
636	func buildProviderContextWindows(cat *modelcatalog.Catalog, defaultModel string, discoveredIDs []string) map[string]int {
637		if cat == nil {
638			return nil
639		}
640		out := make(map[string]int)
641		if defaultModel != "" {
642			if n := cat.ContextWindowForModel(defaultModel); n > 0 {
643				out[defaultModel] = n
644			}
645		}
646		for _, id := range discoveredIDs {
647			if id == "" {
648				continue
649			}
650			if _, exists := out[id]; exists {
651				continue
652			}
653			if n := cat.ContextWindowForModel(id); n > 0 {
654				out[id] = n
655			}
656		}
657		if len(out) == 0 {
658			return nil
659		}
660		return out
661	}
662	
663	// providerSupportsTools returns whether the provider should be advertised as
664	// supporting tools to the routing engine. Defaults to true; only flips to
665	// false when the catalog explicitly marks every relevant model (the
666	// DefaultModel and any DiscoveredIDs) with no_tools=true.
667	func providerSupportsTools(cat *modelcatalog.Catalog, defaultModel string, discoveredIDs []string) bool {
668		if cat == nil {
669			return true
670		}
671		checked := false
672		if defaultModel != "" {
673			if cat.SupportsToolsForModel(defaultModel) {
674				return true
675			}
676			checked = true
677		}
678		for _, id := range discoveredIDs {
679			if id == "" {
680				continue
681			}
682			if cat.SupportsToolsForModel(id) {
683				return true
684			}
685			checked = true
686		}
687		if !checked {
688			return true
689		}
690		return false
691	}
692	
693	func anyProviderSupportsTools(providers []routing.ProviderEntry) bool {
694		for _, p := range providers {
695			if p.SupportsTools {
696				return true
697			}
698		}
699		return false
700	}
