702	func providerUsesLiveDiscovery(providerType string) bool {
703		switch normalizeServiceProviderType(providerType) {
704		case "openai", "openrouter", "lmstudio", "omlx", "ollama", "minimax", "qwen", "zai":
705			return true
706		default:
707			return false
708		}
