711	func (s *service) applyEndpointRoutingCost(entry *routing.ProviderEntry, pcfg ServiceProviderEntry, cat *modelcatalog.Catalog) {
712		if entry == nil {
713			return
714		}
715		if providerTypeIsLocalEndpoint(pcfg.Type) {
716			if s.opts.LocalCostUSDPer1kTokens > 0 {
717				entry.CostUSDPer1kTokens = s.opts.LocalCostUSDPer1kTokens
718				entry.CostSource = routing.CostSourceUserConfig
719			} else {
720				entry.CostUSDPer1kTokens = 0
721				entry.CostSource = routing.CostSourceUnknown
722			}
723			return
724		}
725		if cost, ok := catalogCostUSDPer1kTokens(cat, entry.DefaultModel); ok {
726			entry.CostUSDPer1kTokens = cost
727			entry.CostSource = routing.CostSourceCatalog
728			return
729		}
730		entry.CostUSDPer1kTokens = 0
731		entry.CostSource = routing.CostSourceUnknown
732	}
733	
734	func (s *service) applySubscriptionRoutingCost(entry *routing.HarnessEntry, cat *modelcatalog.Catalog) {
735		if entry == nil || !entry.IsSubscription {
736			return
737		}
738		baseCost, ok := catalogCostUSDPer1kTokens(cat, entry.DefaultModel)
739		if !ok {
740			baseCost, ok = catalogCostUSDPer1kTokens(cat, subscriptionFallbackProfile(entry.Name))
741			if !ok {
742				baseCost = 0
743			}
744		}
745		cost := subscriptionEffectiveCostUSDPer1kTokens(baseCost, entry.QuotaPercentUsed, s.subscriptionCostCurve())
746		entry.Providers = []routing.ProviderEntry{{
747			CostUSDPer1kTokens: cost,
748			CostSource:         routing.CostSourceSubscription,
749		}}
750	}
