761	func subscriptionFallbackProfile(harnessName string) string {
762		switch harnessName {
763		case "claude", "codex", "gemini":
764			return "standard"
765		default:
766			return ""
767		}
768	}
769	
770	func catalogCostUSDPer1kTokens(cat *modelcatalog.Catalog, modelID string) (float64, bool) {
771		if cat == nil || strings.TrimSpace(modelID) == "" {
772			return 0, false
773		}
774		entry, ok := cat.LookupModel(modelID)
775		if !ok {
776			resolved := resolveCatalogCostModel(cat, modelID)
777			if resolved == "" {
778				return 0, false
779			}
780			entry, ok = cat.LookupModel(resolved)
781			if !ok {
782				return 0, false
783			}
784		}
785		input := entry.CostInputPerM
786		if input == 0 {
787			input = entry.CostInputPerMTok
788		}
789		output := entry.CostOutputPerM
790		if output == 0 {
791			output = entry.CostOutputPerMTok
792		}
793		switch {
794		case input > 0 && output > 0:
795			return ((input + output) / 2) / 1000, true
796		case input > 0:
797			return input / 1000, true
798		case output > 0:
799			return output / 1000, true
800		default:
801			return 0, false
802		}
803	}
804	
805	func resolveCatalogCostModel(cat *modelcatalog.Catalog, ref string) string {
806		for _, surface := range []modelcatalog.Surface{
807			modelcatalog.SurfaceAgentOpenAI,
808			modelcatalog.SurfaceAgentAnthropic,
809			modelcatalog.SurfaceCodex,
810			modelcatalog.SurfaceClaudeCode,
811			modelcatalog.SurfaceGemini,
812		} {
813			resolved, err := cat.Resolve(ref, modelcatalog.ResolveOptions{
814				Surface:         surface,
815				AllowDeprecated: true,
816			})
817			if err == nil && resolved.ConcreteModel != "" {
818				return resolved.ConcreteModel
819			}
820		}
821		return ""
822	}
823	
824	func (s *service) subscriptionCostCurve() SubscriptionCostCurve {
825		if s.opts.SubscriptionCostCurve == nil {
826			return defaultSubscriptionCostCurve()
827		}
828		curve := *s.opts.SubscriptionCostCurve
829		def := defaultSubscriptionCostCurve()
830		if curve.FreeUntilPercent == 0 {
831			curve.FreeUntilPercent = def.FreeUntilPercent
832		}
833		if curve.LowUntilPercent == 0 {
834			curve.LowUntilPercent = def.LowUntilPercent
835		}
836		if curve.MediumUntilPercent == 0 {
837			curve.MediumUntilPercent = def.MediumUntilPercent
838		}
839		if curve.LowMultiplier == 0 {
840			curve.LowMultiplier = def.LowMultiplier
841		}
842		if curve.MediumMultiplier == 0 {
843			curve.MediumMultiplier = def.MediumMultiplier
844		}
845		if curve.HighMultiplier == 0 {
846			curve.HighMultiplier = def.HighMultiplier
847		}
848		return curve
849	}
850	
851	func defaultSubscriptionCostCurve() SubscriptionCostCurve {
852		return SubscriptionCostCurve{
853			FreeUntilPercent:   70,
854			LowUntilPercent:    80,
855			MediumUntilPercent: 90,
856			LowMultiplier:      0.1,
857			MediumMultiplier:   0.3,
858			HighMultiplier:     1.2,
859		}
860	}
861	
862	func subscriptionEffectiveCostUSDPer1kTokens(baseCost float64, quotaPercentUsed int, curve SubscriptionCostCurve) float64 {
863		switch {
864		case quotaPercentUsed <= curve.FreeUntilPercent:
865			return 0
866		case quotaPercentUsed <= curve.LowUntilPercent:
867			return baseCost * curve.LowMultiplier
868		case quotaPercentUsed <= curve.MediumUntilPercent:
869			return baseCost * curve.MediumMultiplier
870		default:
871			return baseCost * curve.HighMultiplier
872		}
873	}
874	
875	// probeEndpointDiscoveredIDs returns the foreground /v1/models catalog for one
876	// endpoint. Dispatch routing must not use stale cache hits: a recently dead
877	// endpoint has to be skipped before any chat request is attempted.
878	func (s *service) probeEndpointDiscoveredIDs(ctx context.Context, pcfg ServiceProviderEntry, baseURL string) ([]string, bool) {
879		if baseURL == "" {
880			return nil, false
881		}
882		probeCtx, cancel := context.WithTimeout(ctx, 2*time.Second)
883		defer cancel()
884		ids, err := probeOpenAIModels(probeCtx, baseURL, pcfg.APIKey)
885		if err != nil || len(ids) == 0 {
886			return nil, false
887		}
888		return ids, true
889	}
890	
891	// resolveExecuteRouteWithEngine is the post-engine variant of resolveExecuteRoute.
892	// It is invoked by Execute when the request is under-specified
893	// (no PreResolved, no fully-specified Harness). Returns nil when the request
894	// is already specific enough that the legacy resolveExecuteRoute path applies.
895	func (s *service) resolveExecuteRouteWithEngine(req ServiceExecuteRequest) (*RouteDecision, error) {
896		rr := RouteRequest{
897			Profile:     req.Profile,
898			Model:       req.Model,
899			Provider:    req.Provider,
900			Harness:     req.Harness,
901			ModelRef:    req.ModelRef,
902			Reasoning:   req.Reasoning,
903			Permissions: req.Permissions,
904			CachePolicy: req.CachePolicy,
905			MinPower:    req.MinPower,
906			MaxPower:    req.MaxPower,
907		}
908		dec, err := s.ResolveRoute(context.Background(), rr)
909		if err != nil {
910			if isExplicitPinError(err) {
911				return nil, err
912			}
913			return nil, fmt.Errorf("ResolveRoute: %w", err)
914		}
915		return dec, nil
916	}
917	
918	func providerPreferenceForProfile(cat *modelcatalog.Catalog, profile string) (string, error) {
919		if profile == "" {
920			return routing.ProviderPreferenceLocalFirst, nil
921		}
922		if cat == nil {
923			return "", &ErrUnknownProfile{Profile: profile}
924		}
925		info, ok := cat.Profile(profile)
926		if !ok {
927			return "", &ErrUnknownProfile{Profile: profile}
928		}
929		switch info.ProviderPreference {
930		case routing.ProviderPreferenceLocalOnly, routing.ProviderPreferenceSubscriptionOnly,
931			routing.ProviderPreferenceLocalFirst, routing.ProviderPreferenceSubscriptionFirst:
932			return info.ProviderPreference, nil
933		default:
934			return "", fmt.Errorf("profile %q has unsupported provider preference %q", profile, info.ProviderPreference)
935		}
936	}
