// Package quotastate implements the per-provider quota state machine.
//
// The machine has two states: Available and QuotaExhausted. A provider in
// QuotaExhausted carries a RetryAfter timestamp; once now >= RetryAfter the
// provider is treated as Available again. Header parsing, burn-rate tracking,
// and probe behavior are owned by sibling beads — this package is the
// foundational plumbing they share.
package quotastate

import (
	"sort"
	"sync"
	"time"
)

// State enumerates the per-provider quota states.
type State string

const (
	// StateAvailable means the provider is eligible for routing.
	StateAvailable State = "available"
	// StateQuotaExhausted means the provider is excluded from routing
	// until RetryAfter.
	StateQuotaExhausted State = "quota_exhausted"
)

// Snapshot is the public view of one provider's quota state.
type Snapshot struct {
	State      State
	RetryAfter time.Time
}

// Manager tracks per-provider quota state. The zero value is not usable;
// callers must construct one via NewManager.
type Manager struct {
	mu     sync.RWMutex
	states map[string]entry
}

type entry struct {
	state      State
	retryAfter time.Time
}

// NewManager returns a Manager with no providers tracked.
func NewManager() *Manager {
	return &Manager{states: make(map[string]entry)}
}

// MarkExhausted transitions provider to QuotaExhausted with the given
// retry_after timestamp. A zero or non-future retryAfter still records the
// transition; callers (typically header-parsing siblings) supply the value.
func (m *Manager) MarkExhausted(provider string, retryAfter time.Time) {
	if m == nil || provider == "" {
		return
	}
	m.mu.Lock()
	m.states[provider] = entry{state: StateQuotaExhausted, retryAfter: retryAfter}
	m.mu.Unlock()
}

// MarkAvailable transitions provider back to Available, clearing any
// retry_after timestamp.
func (m *Manager) MarkAvailable(provider string) {
	if m == nil || provider == "" {
		return
	}
	m.mu.Lock()
	delete(m.states, provider)
	m.mu.Unlock()
}

// Get returns the current snapshot for provider, auto-recovering to Available
// when now is at or past the recorded retry_after. Auto-recovery is observed
// (the manager mutates its state) so subsequent calls report Available without
// re-checking the timestamp.
func (m *Manager) Get(provider string, now time.Time) Snapshot {
	if m == nil || provider == "" {
		return Snapshot{State: StateAvailable}
	}
	m.mu.RLock()
	e, ok := m.states[provider]
	m.mu.RUnlock()
	if !ok {
		return Snapshot{State: StateAvailable}
	}
	if e.state == StateQuotaExhausted && !e.retryAfter.IsZero() && !now.Before(e.retryAfter) {
		m.mu.Lock()
		// Re-check under write lock in case another goroutine raced.
		if cur, stillThere := m.states[provider]; stillThere && cur.state == StateQuotaExhausted && !cur.retryAfter.IsZero() && !now.Before(cur.retryAfter) {
			delete(m.states, provider)
		}
		m.mu.Unlock()
		return Snapshot{State: StateAvailable}
	}
	return Snapshot{State: e.state, RetryAfter: e.retryAfter}
}

// Exhausted returns the providers currently in QuotaExhausted whose
// retry_after is strictly in the future, sorted by name. Used by the routing
// engine and by NoViableProviderForNow construction.
func (m *Manager) Exhausted(now time.Time) []Snapshot {
	if m == nil {
		return nil
	}
	m.mu.RLock()
	defer m.mu.RUnlock()
	var names []string
	out := make(map[string]Snapshot, len(m.states))
	for name, e := range m.states {
		if e.state != StateQuotaExhausted {
			continue
		}
		if e.retryAfter.IsZero() || now.Before(e.retryAfter) {
			out[name] = Snapshot{State: e.state, RetryAfter: e.retryAfter}
			names = append(names, name)
		}
	}
	sort.Strings(names)
	result := make([]Snapshot, 0, len(names))
	for _, n := range names {
		s := out[n]
		// Stash provider name in a parallel slice via a wrapper would
		// complicate the API; callers needing the name use ExhaustedNames.
		result = append(result, s)
	}
	return result
}

// ExhaustedNames returns the names of providers currently in QuotaExhausted
// whose retry_after is in the future, sorted alphabetically.
func (m *Manager) ExhaustedNames(now time.Time) []string {
	if m == nil {
		return nil
	}
	m.mu.RLock()
	defer m.mu.RUnlock()
	var names []string
	for name, e := range m.states {
		if e.state != StateQuotaExhausted {
			continue
		}
		if e.retryAfter.IsZero() || now.Before(e.retryAfter) {
			names = append(names, name)
		}
	}
	sort.Strings(names)
	return names
}

package quotastate

import (
	"reflect"
	"testing"
	"time"
)

func TestNewManagerStartsAvailable(t *testing.T) {
	m := NewManager()
	got := m.Get("openai", time.Now())
	if got.State != StateAvailable {
		t.Fatalf("untracked provider: state=%q want %q", got.State, StateAvailable)
	}
	if !got.RetryAfter.IsZero() {
		t.Fatalf("untracked provider has retry_after %v; want zero", got.RetryAfter)
	}
}

func TestMarkExhaustedThenAvailable(t *testing.T) {
	m := NewManager()
	now := time.Date(2026, 5, 1, 12, 0, 0, 0, time.UTC)
	retry := now.Add(30 * time.Second)
	m.MarkExhausted("openai", retry)

	got := m.Get("openai", now)
	if got.State != StateQuotaExhausted {
		t.Fatalf("state=%q want %q", got.State, StateQuotaExhausted)
	}
	if !got.RetryAfter.Equal(retry) {
		t.Fatalf("retry=%v want %v", got.RetryAfter, retry)
	}

	m.MarkAvailable("openai")
	got = m.Get("openai", now)
	if got.State != StateAvailable {
		t.Fatalf("after MarkAvailable: state=%q want %q", got.State, StateAvailable)
	}
}

func TestAutoRecoveryAtRetryAfter(t *testing.T) {
	m := NewManager()
	now := time.Date(2026, 5, 1, 12, 0, 0, 0, time.UTC)
	retry := now.Add(10 * time.Second)
	m.MarkExhausted("openai", retry)

	if got := m.Get("openai", now); got.State != StateQuotaExhausted {
		t.Fatalf("before retry_after: state=%q want %q", got.State, StateQuotaExhausted)
	}
	if got := m.Get("openai", retry); got.State != StateAvailable {
		t.Fatalf("at retry_after: state=%q want %q", got.State, StateAvailable)
	}
	// Auto-recovery is observed: state is cleared.
	if got := m.Get("openai", now); got.State != StateAvailable {
		t.Fatalf("after auto-recovery, before retry_after: state=%q want %q", got.State, StateAvailable)
	}
}

func TestExhaustedNamesFiltersExpired(t *testing.T) {
	m := NewManager()
	now := time.Date(2026, 5, 1, 12, 0, 0, 0, time.UTC)
	m.MarkExhausted("zeta", now.Add(time.Minute))
	m.MarkExhausted("alpha", now.Add(2*time.Minute))
	// Already-expired entry should not show up.
	m.MarkExhausted("beta", now.Add(-time.Minute))

	names := m.ExhaustedNames(now)
	want := []string{"alpha", "zeta"}
	if !reflect.DeepEqual(names, want) {
		t.Fatalf("ExhaustedNames=%v want %v", names, want)
	}
}

func TestNilManagerReportsAvailable(t *testing.T) {
	var m *Manager
	if got := m.Get("openai", time.Now()); got.State != StateAvailable {
		t.Fatalf("nil manager: state=%q want %q", got.State, StateAvailable)
	}
	if got := m.ExhaustedNames(time.Now()); got != nil {
		t.Fatalf("nil manager ExhaustedNames=%v want nil", got)
	}
	// Mutators must not panic.
	m.MarkExhausted("openai", time.Now())
	m.MarkAvailable("openai")
}

