// NoViableProviderForNow reports that Execute had zero eligible providers
// solely because every otherwise-eligible provider is in the quota_exhausted
// state. DDx (and other downstream callers) consume this to pause their drain
// loop and resume after RetryAfter — the earliest expected provider recovery.
//
// This error is distinct from the existing "no candidate" / "config" errors:
// those report that no provider could ever serve the request as configured,
// while NoViableProviderForNow signals a transient condition that is expected
// to clear at RetryAfter.
//
// errors.As-friendly: callers should use errors.As to extract RetryAfter and
// ExhaustedProviders.
type NoViableProviderForNow struct {
	// RetryAfter is the earliest expected provider recovery time across
	// the providers in ExhaustedProviders. It is the time at or after
	// which the caller should retry the request.
	RetryAfter time.Time
	// ExhaustedProviders is the alphabetically sorted list of provider
	// names that are quota_exhausted at the time the error was produced.
	ExhaustedProviders []string
}

func (e *NoViableProviderForNow) Error() string {
	if len(e.ExhaustedProviders) == 0 {
		return fmt.Sprintf("no viable provider until %s: all eligible providers are quota-exhausted", e.RetryAfter.Format(time.RFC3339))
	}
	return fmt.Sprintf("no viable provider until %s: %s quota-exhausted",
		e.RetryAfter.Format(time.RFC3339), strings.Join(e.ExhaustedProviders, ", "))
}

func (e *NoViableProviderForNow) Is(target error) bool {
	switch target.(type) {
	case NoViableProviderForNow, *NoViableProviderForNow:
		return true
	default:
		return errors.Is(errNoViableProviderForNow, target)
	}
}

func (e *NoViableProviderForNow) Unwrap() error {
	return errNoViableProviderForNow
}

