package fizeau

import (
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/quotastate"
)

// markProviderQuotaExhausted transitions the named provider into the
// quota_exhausted state with the supplied retry_after timestamp. The header
// parsing / burn-rate sibling beads call this; this slice exposes the
// transition API but does not produce signals on its own.
func (s *service) markProviderQuotaExhausted(provider string, retryAfter time.Time) {
	if s == nil || s.providerQuotaState == nil {
		return
	}
	s.providerQuotaState.MarkExhausted(provider, retryAfter)
}

// markProviderAvailable transitions the named provider back to the available
// state. The probe-behavior sibling bead is the primary caller; auto-recovery
// at retry_after happens inside the manager itself.
func (s *service) markProviderAvailable(provider string) {
	if s == nil || s.providerQuotaState == nil {
		return
	}
	s.providerQuotaState.MarkAvailable(provider)
}

// providerQuotaSnapshot returns the current quota snapshot for provider.
func (s *service) providerQuotaSnapshot(provider string, now time.Time) quotastate.Snapshot {
	if s == nil || s.providerQuotaState == nil {
		return quotastate.Snapshot{State: quotastate.StateAvailable}
	}
	return s.providerQuotaState.Get(provider, now)
}

