// applyProviderQuotaState populates ProviderEntry.QuotaExhaustedUntil for
// every provider currently in the quota_exhausted state. Routing.Resolve uses
// that field as the last gate; any candidate that fails only this gate is, by
// construction, otherwise eligible — which lets the service translate
// NoViableCandidateError into NoViableProviderForNow at the public boundary.
func (s *service) applyProviderQuotaState(in *routing.Inputs, now time.Time) {
	if in == nil || s == nil || s.providerQuotaState == nil {
		return
	}
	for hi := range in.Harnesses {
		providers := in.Harnesses[hi].Providers
		for pi := range providers {
			name := providers[pi].Name
			if name == "" {
				continue
			}
			snap := s.providerQuotaState.Get(name, now)
			if snap.State == quotastate.StateQuotaExhausted && !snap.RetryAfter.IsZero() && now.Before(snap.RetryAfter) {
				providers[pi].QuotaExhaustedUntil = snap.RetryAfter
			}
		}
		in.Harnesses[hi].Providers = providers
	}
}

